-- A for Acre — seed data
-- Run this AFTER schema.sql, in Supabase → SQL Editor. Safe to re-run — upserts by primary key.

on conflict (slug) do update set
  title = excluded.title, area = excluded.area, corridor = excluded.corridor, lat = excluded.lat, lng = excluded.lng,
  extent_acres = excluded.extent_acres, price_per_acre = excluded.price_per_acre, total_price = excluded.total_price,
  tags = excluded.tags, journey_fit = excluded.journey_fit, soil_type = excluded.soil_type, water_sources = excluded.water_sources,
  road_access = excluded.road_access, fencing = excluded.fencing, electricity = excluded.electricity, images = excluded.images,
  description = excluded.description, taxes = excluded.taxes, suitability = excluded.suitability, legal = excluded.legal,
  nearby_landmarks = excluded.nearby_landmarks, distance_from_bangalore_km = excluded.distance_from_bangalore_km, featured = excluded.featured;

on conflict (name) do nothing;
